// dev_type -> model family
ModelFamily inverter_model_family(uint8_t dev_type) {
  switch (dev_type) {
    case 35:
      return ModelFamily::HYBRID;
    case 1:
    case 21:
      return ModelFamily::STRING;
    default:
      return ModelFamily::UNKNOWN;
  }
}

